/// A character no run is played as, which drafts from nothing.
const EMPTY_DRAFT: Drafted<'static, Cards> = Drafted {
    common: &[],
    uncommon: &[],
    rare: &[],
};

impl sts2_core::CardTable for Cards {
    type Pool = CardPool;
    type Rarity = CardRarity;
    type Target = TargetType;
    type Var = CardVar;

    type Tag = CardTag;

    type Number = CardNumber;
    fn pool(self) -> Option<CardPool> {
        match self {
            Cards::Ironclad(_) => Some(CardPool::Ironclad),
            Cards::Silent(_) => Some(CardPool::Silent),
            Cards::Regent(_) => Some(CardPool::Regent),
            Cards::Necrobinder(_) => Some(CardPool::Necrobinder),
            Cards::Defect(_) => Some(CardPool::Defect),
            Cards::Colorless(_) => None,
            Cards::Curse(_) => None,
            Cards::Event(_) => None,
            Cards::Quest(_) => None,
            Cards::Status(_) => None,
            Cards::Token(_) => None,
            Cards::Deprecated(_) => None,
        }
    }

    fn rarity(self) -> CardRarity {
        self.data().rarity
    }

    fn cost(self) -> Cost {
        self.data().cost
    }

    fn star_cost(self) -> Cost {
        self.data().star_cost
    }

    fn target(self) -> Option<TargetType> {
        match self.data().target {
            Field::Constant(target) => Some(target),
            Field::Computed => None,
        }
    }

    fn unplayable(self) -> bool {
        self.data().keywords.contains(CardKeyword::Unplayable)
    }

    fn gains_block(self) -> bool {
        self.data().gains_block
    }

    fn exhausts(self) -> bool {
        self.data().keywords.contains(CardKeyword::Exhaust)
    }

    fn ethereal(self) -> bool {
        self.data().keywords.contains(CardKeyword::Ethereal)
    }

    fn innate(self) -> bool {
        self.data().keywords.contains(CardKeyword::Innate)
    }

    fn eternal(self) -> bool {
        self.data().keywords.contains(CardKeyword::Eternal)
    }

    fn retains(self) -> bool {
        self.data().keywords.contains(CardKeyword::Retain)
    }

    fn sly(self) -> bool {
        self.data().keywords.contains(CardKeyword::Sly)
    }

    fn tagged(self, tag: CardTag) -> bool {
        self.data().tags.contains(tag)
    }

    fn max_upgrade(self) -> u8 {
        self.data().max_upgrade
    }

    fn power(self) -> Option<bool> {
        match self.data().kind {
            Field::Constant(kind) => Some(kind == CardType::Power),
            Field::Computed => None,
        }
    }

    /// Ordinal over the id, which is what `ModelId.CompareTo` is.
    fn order(self) -> u16 {
        match self {
            Cards::Ironclad(c) => c.order(),
            Cards::Silent(c) => c.order(),
            Cards::Regent(c) => c.order(),
            Cards::Necrobinder(c) => c.order(),
            Cards::Defect(c) => c.order(),
            Cards::Colorless(c) => c.order(),
            Cards::Curse(c) => c.order(),
            Cards::Event(c) => c.order(),
            Cards::Quest(c) => c.order(),
            Cards::Status(c) => c.order(),
            Cards::Token(c) => c.order(),
            Cards::Deprecated(c) => c.order(),
        }
    }

    fn vars(self) -> &'static [sts2_core::CardNumber<CardVar, CardNumber>] {
        self.data().vars
    }

    fn overrides(self) -> sts2_core::Overrides {
        OVERRIDES[usize::from(<Self as sts2_core::CardTable>::order(self))]
    }
}

